import{_ as s,C as i,c as l,o as r,aj as c,j as t,G as a,a as h,w as d}from"./chunks/framework.Bfdr4H5E.js";const v=JSON.parse('{"title":"Collective Market Sentiment","description":"","frontmatter":{"outline":"deep","prev":{"text":"Supply and Demand","link":"/trading-with-pav/supply-and-demand"},"next":{"text":"Price Action","link":"/trading-with-pav/price-action"}},"headers":[],"relativePath":"trading-with-pav/collective-market-sentiment.md","filePath":"trading-with-pav/collective-market-sentiment.md"}'),m={name:"trading-with-pav/collective-market-sentiment.md"};function p(u,e,f,g,b,w){const n=i("GraphComment"),o=i("ClientOnly");return r(),l("div",null,[e[0]||(e[0]=c('<h1 id="collective-market-sentiment" tabindex="-1">Collective Market Sentiment <a class="header-anchor" href="#collective-market-sentiment" aria-label="Permalink to &quot;Collective Market Sentiment&quot;">​</a></h1><p>In this article we are going to explore how the dual auction changes the supply and demand which is due to Collective Market Sentiment.</p><p>Note that price within these swings is not moving in a straight line – it fluctuates constantly. The<br> market is comprised of buyers and sellers all competing through different analysis styles, on<br> different timeframes, with different reasons for wanting to enter or exit.</p><p>We don’t know their individual reasons. It’s the collective sentiment that matters. And price moves with whichever crowd most desperately needs to act.</p><p>It comes down to sentiment of the market participants.</p><p>As individual traders become increasingly bullish, they add to the bullish sentiment of the collective group of buyers. If enough of them do this, the overall sentiment of the whole market becomes bullish, demand overcomes supply, and price rises.</p><p>As individual traders become increasingly bearish, they add to the bearish sentiment of the collective group of sellers. If enough of them do this, the overall sentiment of the whole market becomes bearish, supply overcomes demand, and price falls.</p><ul><li><strong>Price moves with changes in the forces of supply and demand.</strong></li><li><strong>Supply and demand change as the sentiment of the crowd changes.</strong></li><li><strong>And the sentiment of the crowd changes with changes in the bullish or bearish sentiment of the market participants.</strong></li></ul><p>So, here are the key points below:</p><ol><li>Just as we discovered that price is two individuals making buy and sell decision, we have now established that price moves also as a result of the net effect of all market participants making individual trade decisions.</li><li>Some people use fundamentals to make trading or investing decisions. Others use Technicals. Others may even use lunar cycles. It doesn’t matter. At the core level, <strong>it’s all just people making decisions</strong>.</li><li>Price doesn’t move up or down because of fundamentals or Technicals. Individuals form an opinion about market direction. Some of them will act on their opinion – they’ll make a decision to buy or sell.</li><li>The sum of all the buy or sell decisions forms the collective sentiment of the crowd, which may be bullish or bearish. And this collective sentiment of all market participants, leads to a net bullish or bearish order flow, which moves price.</li><li>The most “fundamentally” bullish stock will still fall if the sentiment of the crowd is bearish, and they don’t want to own it.</li><li>The most technically perfect breaking of a neckline of a head and shoulder pattern (which is supposedly bearish) will fail to reach its projected target, if the sentiment of the crowd at this point changes to bullish, and they all want to buy this stock.</li><li>It’s <strong>not about</strong> the <strong>fundamentals</strong> or <strong>Technicals</strong>. <strong>It’s about people… and the decisions they make about market direction</strong>.</li><li>Price changes as supply and demand change… supply and demand change based on the beliefs of market participants, or more correctly on the decisions of market participants to act on their beliefs.</li></ol><h3 id="key-takeaways-from-this-volume-1-introduction" tabindex="-1">Key takeaways from this Volume 1 : INTRODUCTION <a class="header-anchor" href="#key-takeaways-from-this-volume-1-introduction" aria-label="Permalink to &quot;Key takeaways from this Volume 1 : INTRODUCTION&quot;">​</a></h3><div class="tip custom-block"><p class="custom-block-title">TIP</p><ul><li>Price movement results from a supply/demand imbalance.</li><li>Changes in supply and demand occur as sentiment changes within the market participants.</li><li>Price therefore depends on the bullish or bearish sentiment of market participants.</li><li>The net sum of all individual trader decisions and actions, form the Net Order Flow.</li><li>When Net Order Flow is bullish (demand greater than supply), price will rise.</li><li>Price continues to rise until we run out of buyers at higher prices, or until the higher prices attract sellers in sufficient quantity to overcome demand.</li><li>When Net Order Flow is bearish (supply greater than demand), price will fall.</li><li>Price continues to fall until we run out of sellers at lower prices, or until the lower prices attract buyers in sufficient quantity to overcome supply.</li></ul><p>Or more simply:</p><ul><li><strong>Price moves as a collective result of all traders’ bullish or bearish sentiment and their decisions to act in the market (buy or sell).</strong></li></ul></div><p>See you in next <strong>Module 2 : PRICE ACTION &amp; S/R</strong> articles.</p><h2 id="video" tabindex="-1">Video <a class="header-anchor" href="#video" aria-label="Permalink to &quot;Video&quot;">​</a></h2>',14)),e[1]||(e[1]=t("iframe",{width:"560",height:"315",src:"https://www.youtube.com/embed/NxwzJtN3k9Q",title:"YouTube video player",frameborder:"0",allow:"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture",allowfullscreen:""},null,-1)),e[2]||(e[2]=t("p",null,"The above video explains this article in hindi language.",-1)),e[3]||(e[3]=t("h2",{id:"comments",tabindex:"-1"},[h("Comments "),t("a",{class:"header-anchor",href:"#comments","aria-label":'Permalink to "Comments"'},"​")],-1)),a(o,null,{default:d(()=>[a(n)]),_:1})])}const k=s(m,[["render",p]]);export{v as __pageData,k as default};
